bool buildDaisyInvoiceCustomer(const DaisyInvoiceCustomerPayload& in,std::vector<uint8_t>& out,std::string& error){if(!safeText(in.identificationNumber,32)||!optionalSafeText(in.vatNumber,32)||!optionalSafeText(in.seller,64)||!optionalSafeText(in.receiver,64)||!optionalSafeText(in.customer,64)||in.addressLines.size()>4||std::any_of(in.addressLines.begin(),in.addressLines.end(),[](const std::string& v){return !safeText(v,64);})){error="DAISY_INVOICE_CUSTOMER";return false;}std::vector<std::string> fields={in.identificationNumber,in.vatNumber,in.seller,in.receiver,in.customer};fields.insert(fields.end(),in.addressLines.begin(),in.addressLines.end());while(fields.size()>1&&fields.back().empty())fields.pop_back();out.clear();for(size_t i=0;i<fields.size();i++){if(i)tab(out);append(out,fields[i]);}if(out.size()>220){error="DAISY_INVOICE_CUSTOMER";out.clear();return false;}return true;}
bool buildDaisyBarcode(const DaisyBarcodePayload& in,std::vector<uint8_t>& out,std::string& error){const bool numeric=digits(in.data,1,220);bool valid=false;switch(in.type){case 1:valid=digits(in.data,7,7);break;case 2:valid=digits(in.data,12,12);break;case 3:valid=printableAscii(in.data,numeric?18:80);break;case 4:valid=digits(in.data,8,8)&&in.data[0]=='0';break;case 5:valid=digits(in.data,11,11);break;case 6:valid=digits(in.data,1,9);break;case 7:case 8:valid=digits(in.data,1,18);break;case 9:valid=printableAscii(in.data,9);break;case 10:valid=printableAscii(in.data,8);break;case 11:valid=!in.data.empty()&&in.data.size()<=11&&std::all_of(in.data.begin(),in.data.end(),[](unsigned char c){return std::isdigit(c)||(c>='A'&&c<='Z');});break;case 12:valid=!in.data.empty()&&in.data.size()<=14&&std::all_of(in.data.begin(),in.data.end(),[](unsigned char c){return std::isdigit(c)||(c>='A'&&c<='D');});break;case 13:valid=digits(in.data,1,13);break;}if(!valid||(in.position!='C'&&in.position!='R'&&in.position!='L')||in.scale>999||in.heightMm>999){error="DAISY_BARCODE";return false;}out.clear();append(out,std::to_string(in.type));out.push_back(',');append(out,in.data);if(in.optionsSpecified){tab(out);out.push_back(static_cast<uint8_t>(in.position));out.push_back(',');append(out,std::to_string(in.scale));out.push_back(',');append(out,std::to_string(in.heightMm));out.push_back(',');out.push_back(static_cast<uint8_t>(in.printText?'1':'0'));}return true;}
bool buildDaisyCustomerQr(char operation,const std::vector<std::string>& fields,std::vector<uint8_t>& out,std::string& error){if(operation!='Q'&&operation!='P'&&operation!='R'){error="DAISY_CUSTOMER_QR";return false;}if((operation=='Q'&&(fields.size()!=1||!safeText(fields[0],180)))||(operation=='P'&&(fields.empty()||std::any_of(fields.begin(),fields.end(),[](const std::string& v){return !qrTemplateId(v);})))||(operation=='R'&&!fields.empty())){error="DAISY_CUSTOMER_QR";return false;}out.clear();out.push_back(static_cast<uint8_t>(operation));for(const auto& field:fields){out.push_back(',');append(out,field);}return true;}
