bool buildDaisyDisplayConfiguration(char type,const std::string& data,std::vector<uint8_t>& out,std::string& error){bool valid=false;if(type=='R'||type=='C'||type=='S')valid=digits(data,1,6);else if(type>='0'&&type<='9'){if(data=="D")valid=true;else if(!data.empty()&&std::string("IBNEO").find(data[0])!=std::string::npos){const auto comma=data.find(',');const std::string body=data.substr(1,comma==std::string::npos?std::string::npos:comma-1);valid=upperHex(body,20);if(valid&&comma!=std::string::npos)valid=digits(data.substr(comma+1),1,6);}}if(!valid){error="DAISY_DISPLAY_CONFIGURATION";return false;}out.clear();out.push_back(static_cast<uint8_t>(type));out.push_back(',');append(out,data);return true;}
bool buildDaisyCustomerProgram(const DaisyCustomerRecord& in,std::vector<uint8_t>& out,std::string& error){const std::string fields[]={in.eik,in.vatNumber,in.receiver,in.buyer,in.address1,in.address2};if(!safeText(in.eik,32)||std::any_of(std::begin(fields)+1,std::end(fields),[](const std::string& v){return !optionalSafeText(v,64);})){error="DAISY_CUSTOMER_PROGRAM";return false;}out={'P'};for(const auto& field:fields){if(&field!=&fields[0])tab(out);append(out,field);}while(out.size()>1&&out.back()=='\t')out.pop_back();if(out.size()>220){error="DAISY_CUSTOMER_PROGRAM";out.clear();return false;}return true;}
