bool parseDaisyTextReportLine(const std::vector<uint8_t>& raw,DaisyTextReportLine& out,std::string& error){if(raw.size()==5&&raw[0]==0x1a&&raw[1]=='\t'&&raw[2]=='E'&&raw[3]=='\r'&&raw[4]=='\n'){out={};out.font='E';out.end=true;return true;}if(raw.size()<12||raw[0]!=0x1a||raw[7]!='\t'||(raw[8]!='N'&&raw[8]!='B')||raw[9]!='\t'||raw[raw.size()-2]!='\r'||raw.back()!='\n'){error="DAISY_TEXT_REPORT_LINE";return false;}const std::string line(raw.begin()+1,raw.begin()+7),text(raw.begin()+10,raw.end()-2);if(!digits(line,6,6)||text.empty()||text.size()>256||std::any_of(text.begin(),text.end(),[](char c){return c=='\r'||c=='\n';})||!uint32Value(line,out.lineNumber)){error="DAISY_TEXT_REPORT_LINE";return false;}out.font=static_cast<char>(raw[8]);out.text=text;out.end=false;return true;}
